import { directiveCollector, extractFrontmatter } from '../mermaid/parse';

export type Start =
  | { kind: 'date'; date: string }
  | { kind: 'after'; ids: string[] }
  | { kind: 'prev' }; // implicit: right after the previous task (only kept for the very first task)
export type End =
  | { kind: 'dur'; n: number; unit: string }
  | { kind: 'date'; date: string }
  | { kind: 'until'; id: string };

export interface GTask {
  id: string;
  name: string;
  /** done | active | crit | milestone */
  tags: string[];
  start: Start;
  end: End;
  /** the id was generated by us because the source had none */
  autoId?: boolean;
}

/** A line inside a section: a task, or text we keep verbatim (comments, anything unparseable). */
export type GItem = { type: 'task'; task: GTask } | { type: 'raw'; text: string };
export interface GSection {
  name: string; // '' = tasks before any `section` line
  items: GItem[];
}

export interface Gantt {
  title: string;
  dateFormat: string;
  axisFormat?: string;
  todayMarker?: string;
  /** other config lines (excludes, tickInterval, weekday, ...), verbatim, in order */
  header: string[];
  frontmatter?: string;
  preamble?: string[];
  sections: GSection[];
  /** click / accessibility lines etc., verbatim, emitted last */
  extras: string[];
}

export const TAGS = ['done', 'active', 'crit', 'milestone'] as const;
const UNIT_DAYS: Record<string, number> = { d: 1, w: 7, M: 30, y: 365, h: 1 / 24, m: 1 / 1440, s: 1 / 86400, ms: 1 / 86400000 };
const DATE = /^\d{4}-\d{2}-\d{2}$/;
const DUR = /^(\d+(?:\.\d+)?)(ms|s|m|h|d|w|M|y)$/;
const CONFIG = /^(excludes|includes|tickInterval|weekday|weekend|inclusiveEndDates|topAxis|displayMode|accTitle|accDescr)\b/i;

export const toDay = (iso: string) => Math.round(Date.parse(iso + 'T00:00:00Z') / 864e5);
export const fromDay = (d: number) => new Date(Math.round(d) * 864e5).toISOString().slice(0, 10);
export const todayDay = () => toDay(new Date().toISOString().slice(0, 10));

export const emptyGantt = (): Gantt => ({ title: 'Untitled plan', dateFormat: 'YYYY-MM-DD', header: [], sections: [], extras: [] });

export function allTasks(g: Gantt): GTask[] {
  return g.sections.flatMap((s) => s.items.flatMap((i) => (i.type === 'task' ? [i.task] : [])));
}
export const findTask = (g: Gantt, id: string) => allTasks(g).find((t) => t.id === id);

/* ------------------------------------------------------------------ parse */

function parseTask(line: string): GTask | null {
  const i = line.indexOf(':');
  if (i < 1) return null;
  const name = line.slice(0, i).trim();
  if (!name) return null;
  const meta = line.slice(i + 1).split(',').map((s) => s.trim());
  if (meta.some((m) => !m)) return null;
  const tags: string[] = [];
  while (meta.length && (TAGS as readonly string[]).includes(meta[0])) tags.push(meta.shift()!);

  const start = (tok: string): Start | null => {
    if (DATE.test(tok)) return { kind: 'date', date: tok };
    const m = /^after\s+(.+)$/.exec(tok);
    return m ? { kind: 'after', ids: m[1].split(/\s+/) } : null;
  };
  const end = (tok: string): End | null => {
    const d = DUR.exec(tok);
    if (d) return { kind: 'dur', n: Number(d[1]), unit: d[2] };
    if (DATE.test(tok)) return { kind: 'date', date: tok };
    const u = /^until\s+(\S+)$/.exec(tok);
    return u ? { kind: 'until', id: u[1] } : null;
  };

  let id: string | undefined;
  let s: Start | null;
  let e: End | null;
  if (meta.length === 1) {
    s = { kind: 'prev' };
    e = end(meta[0]);
  } else if (meta.length === 2) {
    s = start(meta[0]);
    e = end(meta[1]);
  } else if (meta.length === 3) {
    id = meta[0];
    if (!/^[^\s,:#;]+$/.test(id)) return null;
    s = start(meta[1]);
    e = end(meta[2]);
  } else return null;
  if (!s || !e) return null;
  return { id: id ?? '', name, tags, start: s, end: e, ...(id ? {} : { autoId: true }) };
}

export function parseGantt(input: string): { gantt: Gantt; warnings: string[] } {
  const warnings: string[] = [];
  const { text, frontmatter, lineOffset } = extractFrontmatter(input);
  const directives = directiveCollector();
  const g = emptyGantt();
  g.title = '';
  g.dateFormat = '';
  const lines = text.split(/\r?\n/);
  // dateFormat decides whether task lines can be understood at all
  const df = lines.map((l) => /^\s*dateFormat\s+(.+?)\s*$/i.exec(l)).find(Boolean);
  const supported = !df || df[1] === 'YYYY-MM-DD';
  if (!supported) warnings.push(`dateFormat "${df![1]}" isn't supported by the visual editor — edit this chart as text.`);

  let cur: GSection | null = null;
  const section = () => (cur ??= (g.sections.push({ name: '', items: [] }), g.sections[g.sections.length - 1]));

  lines.forEach((raw, i) => {
    const lineNo = i + 1 + lineOffset;
    const line = raw.trim();
    if (directives.feed(line) || !line) return;
    let m: RegExpExecArray | null;
    if (/^gantt\s*$/i.test(line)) return;
    if ((m = /^title\s+(.+)$/i.exec(line))) return void (g.title = m[1]);
    if ((m = /^dateFormat\s+(.+)$/i.exec(line))) return void (g.dateFormat = m[1].trim());
    if ((m = /^axisFormat\s+(.+)$/i.exec(line))) return void (g.axisFormat = m[1].trim());
    if ((m = /^todayMarker\s+(.+)$/i.exec(line))) return void (g.todayMarker = m[1].trim());
    if ((m = /^section\s*(.*)$/i.exec(line))) {
      cur = { name: m[1].trim(), items: [] };
      g.sections.push(cur);
      return;
    }
    if (CONFIG.test(line)) return void g.header.push(line);
    if (/^click\b/i.test(line)) return void g.extras.push(line);
    if (line.startsWith('%%')) {
      if (cur) cur.items.push({ type: 'raw', text: line });
      else g.header.push(line);
      return;
    }
    const task = supported && line.includes(':') ? parseTask(line) : null;
    if (task) section().items.push({ type: 'task', task });
    else {
      section().items.push({ type: 'raw', text: line });
      if (supported) warnings.push(`Line ${lineNo}: could not parse — kept as-is: "${line}"`);
    }
  });

  if (!g.dateFormat) g.dateFormat = 'YYYY-MM-DD';
  if (!g.title) g.title = '';

  // Give id-less tasks an id, then make "starts after the previous task" explicit.
  const tasks = allTasks(g);
  const used = new Set(tasks.filter((t) => t.id).map((t) => t.id));
  let n = 1;
  for (const t of tasks) {
    if (t.id) continue;
    while (used.has(`task${n}`)) n++;
    t.id = `task${n}`;
    used.add(t.id);
  }
  tasks.forEach((t, k) => {
    if (t.start.kind === 'prev' && k > 0) t.start = { kind: 'after', ids: [tasks[k - 1].id] };
  });

  return {
    gantt: {
      ...g,
      ...(frontmatter !== undefined ? { frontmatter } : {}),
      ...(directives.preamble.length ? { preamble: directives.preamble } : {}),
    },
    warnings,
  };
}

/* -------------------------------------------------------------- serialize */

const clean = (s: string) => s.replace(/[#;]/g, '').replace(/:/g, ' -').trim() || 'Untitled';

export function serializeGantt(g: Gantt): string {
  const lines: string[] = [];
  if (g.frontmatter?.trim()) lines.push('---', g.frontmatter.replace(/\s+$/, ''), '---');
  lines.push(...(g.preamble ?? []));
  lines.push('gantt');
  if (g.title) lines.push(`    title ${g.title}`);
  lines.push(`    dateFormat ${g.dateFormat || 'YYYY-MM-DD'}`);
  if (g.axisFormat) lines.push(`    axisFormat ${g.axisFormat}`);
  if (g.todayMarker) lines.push(`    todayMarker ${g.todayMarker}`);
  for (const h of g.header) lines.push(`    ${h}`);

  const tasks = allTasks(g);
  const referenced = new Set<string>();
  for (const t of tasks) {
    if (t.start.kind === 'after') t.start.ids.forEach((id) => referenced.add(id));
    if (t.end.kind === 'until') referenced.add(t.end.id);
  }
  const prev = new Map<string, string | undefined>();
  tasks.forEach((t, k) => prev.set(t.id, tasks[k - 1]?.id));

  const taskLine = (t: GTask) => {
    const withId = !t.autoId || referenced.has(t.id);
    let start: string | null =
      t.start.kind === 'date' ? t.start.date : t.start.kind === 'after' ? `after ${t.start.ids.join(' ')}` : null;
    if (start === null && withId) start = prev.get(t.id) ? `after ${prev.get(t.id)}` : fromDay(todayDay());
    const end =
      t.end.kind === 'dur' ? `${t.end.n}${t.end.unit}` : t.end.kind === 'date' ? t.end.date : `until ${t.end.id}`;
    const parts = [...t.tags, ...(withId ? [t.id] : []), ...(start === null ? [] : [start]), end];
    return `    ${clean(t.name)} :${parts.join(', ')}`;
  };

  for (const s of g.sections) {
    if (s.name) lines.push(`    section ${s.name}`);
    for (const it of s.items) lines.push(it.type === 'task' ? taskLine(it.task) : `    ${it.text}`);
  }
  for (const x of g.extras) lines.push(`    ${x}`);
  return lines.join('\n') + '\n';
}

/* --------------------------------------------------------------- schedule */

export interface Sched {
  start: number;
  end: number;
}

/** Day numbers (days since 1970-01-01) for every task. Calendar days; `excludes` is not applied. */
export function schedule(g: Gantt, today = todayDay()): Map<string, Sched> {
  const tasks = new Map(allTasks(g).map((t) => [t.id, t]));
  const memo = new Map<string, Sched>();
  const busy = new Set<string>();
  const get = (id: string): Sched => {
    const hit = memo.get(id);
    if (hit) return hit;
    const t = tasks.get(id);
    if (!t || busy.has(id)) return { start: today, end: today + 1 };
    busy.add(id);
    const start =
      t.start.kind === 'date'
        ? toDay(t.start.date)
        : t.start.kind === 'after'
          ? t.start.ids.length
            ? Math.max(...t.start.ids.map((x) => get(x).end))
            : today
          : today;
    const end =
      t.end.kind === 'dur'
        ? start + t.end.n * (UNIT_DAYS[t.end.unit] ?? 1)
        : t.end.kind === 'date'
          ? toDay(t.end.date)
          : tasks.has(t.end.id)
            ? get(t.end.id).start
            : start + 1;
    busy.delete(id);
    const r = { start, end };
    memo.set(id, r);
    return r;
  };
  for (const id of tasks.keys()) get(id);
  return memo;
}

/* -------------------------------------------------------------- operations */

const clone = (g: Gantt): Gantt => structuredClone(g);
const mut = (g: Gantt, id: string) => {
  const c = clone(g);
  return { c, t: findTask(c, id) };
};

export function dependsOn(g: Gantt, id: string, onId: string, seen = new Set<string>()): boolean {
  if (id === onId) return true;
  if (seen.has(id)) return false;
  seen.add(id);
  const t = findTask(g, id);
  if (!t) return false;
  const deps = [...(t.start.kind === 'after' ? t.start.ids : []), ...(t.end.kind === 'until' ? [t.end.id] : [])];
  return deps.some((d) => dependsOn(g, d, onId, seen));
}

export function uniqueId(g: Gantt, base: string): string {
  const used = new Set(allTasks(g).map((t) => t.id));
  let id = base;
  for (let n = 2; used.has(id); n++) id = `${base}${n}`;
  return id;
}

/** Move to a new start day. A task that followed others detaches and gets a fixed date. */
export function moveTask(g: Gantt, id: string, newStart: number): Gantt {
  const sc = schedule(g).get(id);
  const { c, t } = mut(g, id);
  if (!t || !sc) return g;
  const s = Math.round(newStart);
  const len = sc.end - sc.start;
  t.start = { kind: 'date', date: fromDay(s) };
  if (t.end.kind === 'date') t.end = { kind: 'date', date: fromDay(s + len) };
  else if (t.end.kind === 'until') t.end = { kind: 'dur', n: Math.max(1, Math.round(len)), unit: 'd' };
  return c;
}

export function resizeTask(g: Gantt, id: string, days: number): Gantt {
  const sc = schedule(g).get(id);
  const { c, t } = mut(g, id);
  if (!t || !sc) return g;
  const d = Math.max(1, Math.round(days));
  if (t.end.kind === 'date') t.end = { kind: 'date', date: fromDay(sc.start + d) };
  else if (t.end.kind === 'dur' && t.end.unit === 'w' && d % 7 === 0) t.end = { kind: 'dur', n: d / 7, unit: 'w' };
  else t.end = { kind: 'dur', n: d, unit: 'd' };
  return c;
}

/** Make `targetId` start after `sourceId`; null if that would create a loop. */
export function linkTask(g: Gantt, targetId: string, sourceId: string): Gantt | null {
  if (targetId === sourceId || dependsOn(g, sourceId, targetId)) return null;
  const { c, t } = mut(g, targetId);
  if (!t) return g;
  t.start = { kind: 'after', ids: [sourceId] };
  return c;
}

export function addTask(g: Gantt, sectionIdx: number, milestone = false): { gantt: Gantt; id: string } {
  const c = clone(g);
  if (!c.sections.length) c.sections.push({ name: '', items: [] });
  const si = Math.min(Math.max(sectionIdx, 0), c.sections.length - 1);
  const id = uniqueId(c, milestone ? 'milestone' : 'task');
  const last = [...c.sections[si].items].reverse().find((i) => i.type === 'task');
  const sc = schedule(c);
  const start: Start = last
    ? { kind: 'after', ids: [(last as { task: GTask }).task.id] }
    : { kind: 'date', date: fromDay(sc.size ? Math.max(...[...sc.values()].map((s) => s.end)) : todayDay()) };
  c.sections[si].items.push({
    type: 'task',
    task: { id, name: milestone ? 'New milestone' : 'New task', tags: milestone ? ['milestone'] : [], start, end: { kind: 'dur', n: milestone ? 0 : 5, unit: 'd' } },
  });
  return { gantt: c, id };
}

/** Remove a task; anything that followed it keeps its current dates. */
export function deleteTask(g: Gantt, id: string): Gantt {
  const sc = schedule(g);
  const c = clone(g);
  for (const t of allTasks(c)) {
    if (t.start.kind === 'after' && t.start.ids.includes(id)) {
      const ids = t.start.ids.filter((x) => x !== id);
      t.start = ids.length ? { kind: 'after', ids } : { kind: 'date', date: fromDay(sc.get(t.id)?.start ?? todayDay()) };
    }
    if (t.end.kind === 'until' && t.end.id === id) {
      const s = sc.get(t.id);
      t.end = { kind: 'dur', n: Math.max(1, Math.round(s ? s.end - s.start : 1)), unit: 'd' };
    }
  }
  for (const s of c.sections) s.items = s.items.filter((i) => !(i.type === 'task' && i.task.id === id));
  return c;
}

export function renameTaskId(g: Gantt, oldId: string, newId: string): Gantt | null {
  if (!/^[^\s,:#;]+$/.test(newId) || (newId !== oldId && findTask(g, newId))) return null;
  const c = clone(g);
  for (const t of allTasks(c)) {
    if (t.id === oldId) {
      t.id = newId;
      t.autoId = false;
    }
    if (t.start.kind === 'after') t.start.ids = t.start.ids.map((x) => (x === oldId ? newId : x));
    if (t.end.kind === 'until' && t.end.id === oldId) t.end.id = newId;
  }
  return c;
}

export function updateTask(g: Gantt, id: string, fn: (t: GTask) => void): Gantt {
  const { c, t } = mut(g, id);
  if (t) fn(t);
  return c;
}
